from pathlib import Path
import json,hashlib

project=Path(__file__).resolve().parent
source=project/'source/complete-review'
manifest=json.loads((source/'source-manifest.json').read_text())
pages=[('lifecycle','Packet lifecycle','motion'),('builder','Network Builder','workbench'),('evidence','Evidence workspaces','evidence'),('connected','Connected workspaces','connected')]
nav='<nav class="review-navigation" aria-label="Design reviews"><a href="/review/">Review index</a>'+''.join(f'<a href="/review/{slug}.html">{title}</a>' for slug,title,_ in pages)+'<a href="/review/viewport.html">Viewport review</a><a href="/">Main application</a></nav>'
css='''html{color-scheme:light;--review-bg:#f3f5f7;--review-ink:#172332;--review-muted:#526273;--review-rim:#d9e0e8}html[data-theme=dark]{color-scheme:dark;--review-bg:#171a20;--review-ink:#eef1f6;--review-muted:#a7afbc;--review-rim:#465365}*{box-sizing:border-box}body{margin:0;background:var(--review-bg);color:var(--review-ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:inherit}.review-navigation{display:flex;gap:8px;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:thin;max-width:1280px;margin:auto;padding:12px 16px}.review-navigation a{flex:0 0 auto;white-space:nowrap;display:flex;align-items:center;min-height:44px;padding:8px 12px;border-radius:14px;text-decoration:none;color:var(--review-muted)}.review-navigation a[aria-current=page]{background:color-mix(in srgb,var(--review-ink) 8%,transparent);color:var(--review-ink)}a:focus-visible{outline:2px solid #3078d7;outline-offset:3px}.review-content{max-width:1280px;margin:auto}.review-index{max-width:960px;margin:48px auto;padding:0 24px 64px}.review-index h1{font-size:clamp(32px,5vw,52px);letter-spacing:-.04em;line-height:1.1;max-width:650px}.review-index p{color:var(--review-muted);max-width:650px}.review-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px;margin:32px 0}.review-card{display:block;text-decoration:none;border:1px solid var(--review-rim);border-radius:24px;padding:26px;min-height:160px;background:color-mix(in srgb,var(--review-bg) 90%,white)}.review-card h2{font-size:21px;letter-spacing:-.02em;margin:0 0 10px}.review-card p{margin:0}.review-note{margin-top:32px;font-size:13px}'''
head=lambda title:'<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="robots" content="noindex"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · HOPSCOTCH Design Review</title><style>'+css+'</style></head><body>'
theme='''<script>(()=>{const owner=document.querySelector('.review-content>[data-theme]');if(!owner)return;const sync=()=>document.documentElement.dataset.theme=owner.dataset.theme;new MutationObserver(sync).observe(owner,{attributes:true,attributeFilter:['data-theme']});sync();})();</script>'''
dist=project.parent/'public/review';dist.mkdir(parents=True,exist_ok=True)
descriptions=['Inspect packets, read fields, modify bytes, and follow complete protocol lifecycles.','Author a network, inspect causal records, and connect results to the forwarding path.','Explore measured facts, captured frames, geography, and AS relationships.','Follow one request and retain context when opening related workspaces.']
for (slug,title,path),entry in zip(pages,manifest):
    text=(source.parent/entry['path']).resolve().read_text();assert hashlib.sha256(text.encode()).hexdigest()==entry['sha256']
    (dist/(slug+'.html')).write_text(head(title)+nav.replace(f'href="/review/{slug}.html"',f'aria-current="page" href="/review/{slug}.html"')+'<div class="review-content">'+text+'</div>'+theme+'</body></html>')
cards=''.join(f'<a class="review-card" href="/review/{slug}.html"><h2>{title}</h2><p>{description}</p></a>' for (slug,title,_),description in zip(pages,descriptions))
(dist/'index.html').write_text(head('Review index')+nav.replace('href="/review/"','aria-current="page" href="/review/"')+'<main class="review-index"><p>HOPSCOTCH · Design review</p><h1>One visual system.<br>Four places to inspect it.</h1><p>The current review studies share typography, responsive composition, materials, protocol colors, and motion. Each study has Light, Dark, and System appearance controls.</p><div class="review-grid">'+cards+'</div><p class="review-note">This review contains the October 10 design candidate. Visual verification and integration are in progress. These studies include reference fixtures; they do not replace the main application. Safari, physical phone, accessibility, and owner acceptance remain open.</p></main></body></html>')

print('Built 4 standalone studies and review index from the frozen source manifest')
